function morphshape4(ctx,ctrans,frame,ratio,time){
	var pathData="M -6688 -6688 -206 -206 L -6688 -6688 234 234 -6448 -181 234 234 -6448 -181 -206 -206 -6688 -6688 -206 -206";
	ctx.fillStyle=tocolor(ctrans.apply([Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(0)/65535),Math.round(204+ratio*(1)/65535),((Math.round(31+ratio*(0)/65535))/255)]));
	drawMorphPath(ctx,pathData,ratio,false);

	ctx.fill("evenodd");
	var pathData="M -6688 -6688 -206 -206 L -6448 -181 -206 -206 -6448 -181 234 234 -6688 -6688 234 234 -6688 -6688 -206 -206 Z";
	var scaleMode = "NORMAL";
	ctx.strokeStyle=tocolor(ctrans.apply([Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(1)/65535),((Math.round(0+ratio*(0)/65535))/255)]));
	ctx.lineWidth=0.0+ratio*(0)/65535;
	ctx.lineCap="round";
	ctx.lineJoin="round";
	drawMorphPath(ctx,pathData,ratio,true,scaleMode);

}

